import { registerHooks } from 'node:module';
// Native Node tests resolve this one TypeScript implementation; Next resolves
// the emitted .js specifier normally. Every other import retains strict resolution.
registerHooks({ resolve(specifier, context, nextResolve) {
  if (specifier === './topic-placement-graph') return { url: new URL('../../lib/topic-placement-graph.ts', import.meta.url).href, shortCircuit: true };
  return nextResolve(specifier, context);
} });
export function graphFixture() {
  const nodes = [['root',null],['a','root'],['b','root'],['t','a'],['child','t']].map(([id,parent_id],i) => ({id,parent_id,name:id,sort_order:i,library_id:'library'}));
  return {version:122,library_id:'library',revision:'a'.repeat(32),root_id:'root',nodes,
    edges:[...nodes.filter(n=>n.parent_id).map(n=>({edge_key:`primary:${n.id}`,parent_id:n.parent_id,topic_id:n.id,sort_order:n.sort_order,kind:'primary'})),
      {edge_key:'placement:alias',parent_id:'b',topic_id:'t',sort_order:0,kind:'placement'}]};
}
export function graphFromNodes(libraryId, nodes) {
 return {version:122,library_id:libraryId,revision:'c'.repeat(32),root_id:nodes.find(n=>n.parent_id===null)?.id??null,
   nodes:nodes.map((n,i)=>({...n,sort_order:n.sort_order??i,library_id:libraryId})),
   edges:nodes.filter(n=>n.parent_id).map((n,i)=>({edge_key:`primary:${n.id}`,parent_id:n.parent_id,topic_id:n.id,sort_order:n.sort_order??i,kind:'primary'}))};
}
export function graphFromTree(libraryId, topics) {
 const rows=[];function visit(items,parent_id=null){items.forEach((n,i)=>{rows.push({id:n.id,name:n.name,parent_id,sort_order:i});visit(n.children,n.id);});}visit(topics);return graphFromNodes(libraryId,rows);
}

